import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Open Cube OS 文档","description":"","frontmatter":{},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),d={name:"zh/index.md"};function i(o,e,h,s,n,c){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="open-cube-os-文档" tabindex="-1">Open Cube OS 文档 <a class="header-anchor" href="#open-cube-os-文档" aria-label="Permalink to &quot;Open Cube OS 文档&quot;">​</a></h1><p>欢迎使用 Open Cube OS 文档中心 - 这是一套从头编写、直接启动进 Ring 3 的 x86_64 内核（L0 是纯服务内核；整个用户世界 —— ush Shell、TUI 桌面、中文控制台、8 个融合大应用 —— 都在 <code>ocos/l1apps/</code> 下的 L1 里）。</p><p>所有内容均基于真实代码库编写：命令计数、接口表和行统计均为 机器生成（<code>make api-docs</code> -&gt; <code>docs/data/*.json</code>），且手册页引用 了实现其描述内容的文件。</p><h2 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h2><ul><li>系统新手：<a href="./manual/getting-started.html">快速上手</a></li><li>命令面：<a href="./manual/mega-apps.html">八大融合应用</a></li><li>想要构建：<a href="./dev/environment.html">开发环境</a> 然后 <a href="./root/BUILDING.html">BUILDING.md</a></li><li>想要扩展：<a href="./l1/overview.html">Ring-3 应用开发</a></li><li>架构问题：<a href="./root/ARCHITECTURE.html">ARCHITECTURE.md</a> 然后 <a href="./arch/">arch/</a> 下的深度剖析</li><li>出了问题：<a href="./troubleshooting/common-errors.html">问题排查</a></li><li>融合应用的故事：<a href="./release/3.0.0-WP-l1apps-merge.html">3.0.0-WP-l1apps-merge</a></li></ul><h2 id="文档库" tabindex="-1">文档库 <a class="header-anchor" href="#文档库" aria-label="Permalink to &quot;文档库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块</th><th>内容</th></tr></thead><tbody><tr><td><a href="./manual/">manual/</a></td><td>用户手册：大应用、启动、Shell、文件、网络、TUI、OTA、恢复 + 全部 292 个命令参考页</td></tr><tr><td><a href="./dev/">dev/</a></td><td>开发者手册：环境、构建、QEMU、调试、测试、PR 门槛、可移植性、风格</td></tr><tr><td><a href="./arch/">arch/</a></td><td>架构深度剖析：启动流、内存、调度器、中断、Ring 3、VFS、网络、驱动、TUI</td></tr><tr><td><a href="./l1/">l1/</a></td><td>Ring-3 应用开发：接口面地图、应用解剖、向导库、应用编写教程、服务家族</td></tr><tr><td><a href="./drivers/">drivers/</a></td><td>驱动上手手册：16 个家族</td></tr><tr><td><a href="./troubleshooting/">troubleshooting/</a></td><td>错误目录与 QEMU 调试</td></tr><tr><td><a href="./internals/">internals/</a></td><td>子系统内幕：看门狗、klog、健康、崩溃转储、密码学种子、OTA/A-B</td></tr><tr><td><a href="./release/">release/</a></td><td>发布工程：流程 SOP、版本号、网站与 Wiki 同步</td></tr></tbody></table><h2 id="速览-3-0-0-wp-l1apps-merge" tabindex="-1">速览（3.0.0-WP-l1apps-merge） <a class="header-anchor" href="#速览-3-0-0-wp-l1apps-merge" aria-label="Permalink to &quot;速览（3.0.0-WP-l1apps-merge）&quot;">​</a></h2><ul><li>296 条 Shell 命令 —— 284 个 Ring-3 注册表应用（含 8 个融合 大应用）+ 12 个 ush 内建，L0 零命令（guest 内 <code>help -a</code>）</li><li>20 个 SYS_L1SVC 服务类别 / 208 个编号操作 （INTERFACES.md、l1svc_defs.h）</li><li>54 个系统调用（<code>ocos/services/sysapi/interface/svc_sysapi_syscall.h</code>）</li><li>158,474 行原创源码，764 个文件</li><li>Apache 2.0，每个文件带 SPDX 标签</li></ul>',9)])])}const u=a(d,[["render",i]]);export{m as __pageData,u as default};
